<?php if($data['selected_space']!==null): $space=$data['selected_space']; $size=\Samla\Core\Web\StorageSizeInput::display((int)$space['quota_bytes']);if(isset($data['form_values'])){$size=['value'=>$data['form_values']['quota_value'],'unit'=>$data['form_values']['quota_unit']];} ?>
<p><a href="/administration/spaces">Alle Speicherbereiche</a></p>
<section class="panel auth-panel"><h2><?= $e($space['name']) ?></h2><?php if($space['owner_id']!==null): ?><p>Persönlicher Bereich von <strong><?= $e($space['owner_name']) ?></strong>. Die Eigentümerzuordnung wird automatisch verwaltet; Änderungen von Name und Quote bleiben bei der nächsten Anmeldung erhalten.</p><?php else: ?><p>Gemeinsamer Bereich.</p><?php endif ?><p class="subtle"><?= $e(number_format($space['used_bytes']/1048576,2,',','.')) ?> MiB belegt, einschließlich Versionen und Papierkorb.</p>
<form method="post" action="/administration/spaces/update" class="settings-form"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($space['id']) ?>"><input type="hidden" name="expected" value="<?= $e($space['fingerprint']) ?>"><label for="space-name">Name</label><input id="space-name" name="name" value="<?= $e($data['form_values']['name']??$space['name']) ?>" required maxlength="255"><label for="space-quota">Speicherquote</label><div class="size-input"><input id="space-quota" name="quota_value" inputmode="decimal" value="<?= $e($size['value']) ?>" required aria-describedby="quota-help"><label class="sr-only" for="space-unit">Einheit der Speicherquote</label><select id="space-unit" name="quota_unit"><?php foreach(\Samla\Core\Web\StorageSizeInput::UNITS as$unit=>$factor): ?><option value="<?= $e($unit) ?>" <?= $size['unit']===$unit?'selected':'' ?>><?= $e($unit) ?></option><?php endforeach ?></select></div><p id="quota-help" class="field-note">GB = 1 Milliarde Bytes, GiB = 1.073.741.824 Bytes. Maximal 1 TiB; bis zu sechs Nachkommastellen, ohne Rundung.</p><p class="field-note">Die Quote umfasst aktuelle Inhalte, Versionen und Papierkorb. Sie darf nicht unter dem aktuellen Verbrauch liegen.</p><button class="button" type="submit">Bereich speichern</button></form>
<p><a class="button button-outline" href="<?= $e('/permissions?'.http_build_query(['space'=>$space['id']])) ?>">Gruppenrechte für diesen Bereich</a></p></section>
<details class="panel file-action danger-zone"><summary>Bereich löschen</summary><div class="disclosure-content"><?php if($space['owner_id']!==null): ?><p>Persönliche Bereiche werden hier auch im leeren Zustand nicht gelöscht. Die Austritts- und Löschrichtlinie muss dafür ausdrücklich festgelegt werden.</p><?php endif ?><p>Dies löscht ausschließlich einen vollständig leeren Bereich und seine Rechtezuweisungen. Dateien und Ordner, auch im Papierkorb, müssen vorher separat bereinigt werden. Aktive Sperren verhindern die Löschung.</p><form method="post" action="/administration/spaces/delete" class="settings-form"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($space['id']) ?>"><input type="hidden" name="expected" value="<?= $e($space['fingerprint']) ?>"><label class="checkbox-label"><input type="checkbox" name="confirm" value="1" required> Leeren Bereich „<?= $e($space['name']) ?>“ endgültig löschen</label><button class="button button-danger" type="submit" <?= $space['entry_count']!==0||$space['owner_id']!==null?'disabled':'' ?>>Leeren Bereich löschen</button></form></div></details>
<?php endif ?>
<?php if($data['show_create']??false): ?><section class="panel auth-panel" id="new-space"><h2>Neuen Speicherbereich anlegen</h2><form method="post" action="/administration/spaces/create" class="settings-form"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><label for="new-space-name">Name</label><input id="new-space-name" name="name" value="<?= $e($data['form_values']['name']??'') ?>" required maxlength="255"><label for="new-space-quota">Speicherquote</label><div class="size-input"><input id="new-space-quota" name="quota_value" value="<?= $e($data['form_values']['quota_value']??'') ?>" inputmode="decimal" required placeholder="Zum Beispiel 10"><label class="sr-only" for="new-space-unit">Einheit der Speicherquote</label><select id="new-space-unit" name="quota_unit"><?php foreach(\Samla\Core\Web\StorageSizeInput::UNITS as$unit=>$factor): ?><option value="<?= $e($unit) ?>" <?= ($data['form_values']['quota_unit']??'GB')===$unit?'selected':'' ?>><?= $e($unit) ?></option><?php endforeach ?></select></div><p class="field-note">GB = 1 Milliarde Bytes, GiB = 1.073.741.824 Bytes. Maximal 1 TiB.</p><p class="field-note">Gruppenrechte werden anschließend ausdrücklich vergeben. Die Anlage verleiht niemandem automatisch Inhaltszugriff.</p><button class="button" type="submit">Bereich anlegen</button></form></section>


